import {
    GET_SITES,
    GET_SITE_ALERTS,
    GET_SITES_ALL,
    GET_SITE_ALERTS_ALL,
    DELETE_SITE,
    ADD_SITE,
    PATCH_SITE,
    UPDATE_SITE_ALERT,
    EXPORT_MISP,
    GET_SITE_STATISTICS
} from '../actions/types.js';

const initialState = {
    sites: [],
    sitesCount: 0,
    sitesNext: null,
    sitesPrevious: null,
    alerts: [],
    alertsCount: 0,
    alertsNext: null,
    alertsPrevious: null,
    // Stats-only: all items loaded at once
    allSites: [],
    allAlerts: [],
    statistics: {
        total: 0,
        malicious: 0,
        takedownRequests: 0,
        legalTeam: 0
    }
};

export default function (state = initialState, action) {
    switch (action.type) {
        case GET_SITES: {
            const newResults = action.payload.results || action.payload;

            if (!action.payload.results) {
                return {
                    ...state,
                    sites: Array.isArray(newResults) ? newResults.slice().sort((a, b) => b.rtir - a.rtir) : [],
                    sitesCount: Array.isArray(newResults) ? newResults.length : 0,
                    sitesNext: null,
                    sitesPrevious: null
                };
            }

            const newMap = new Map(newResults.map(s => [s.id, s]));
            const merged = state.sites.map(s => newMap.has(s.id) ? newMap.get(s.id) : s);
            newResults.forEach(s => { if (!state.sites.find(existing => existing.id === s.id)) merged.push(s); });

            return {
                ...state,
                sites: merged.sort((a, b) => b.rtir - a.rtir),
                sitesCount: action.payload.count || state.sitesCount,
                sitesNext: action.payload.next || null,
                sitesPrevious: action.payload.previous || null
            };
        }

        case GET_SITE_ALERTS: {
            const newResults = action.payload.results || action.payload;
            
            if (!action.payload.results) {
                return {
                    ...state,
                    alerts: newResults,
                    alertsCount: newResults.length,
                    alertsNext: null,
                    alertsPrevious: null
                };
            }
            
            const existingIds = new Set(state.alerts.map(a => a.id));
            const uniqueNewAlerts = newResults.filter(alert => !existingIds.has(alert.id));
            
            return {
                ...state,
                alerts: [...state.alerts, ...uniqueNewAlerts],
                alertsCount: action.payload.count || state.alertsCount,
                alertsNext: action.payload.next || null,
                alertsPrevious: action.payload.previous || null
            };
        }

        case DELETE_SITE:
            return {
                ...state,
                sites: state.sites.filter(site => site.id !== action.payload),
                sitesCount: Math.max(0, state.sitesCount - 1)
            };

        case ADD_SITE:
            return {
                ...state,
                sites: [...state.sites, action.payload].sort((a, b) => b.rtir - a.rtir),
                sitesCount: state.sitesCount + 1
            };

        case PATCH_SITE:
            return {
                ...state,
                sites: state.sites.map(site =>
                    site.id === action.payload.id ? action.payload : site
                ).sort((a, b) => b.rtir - a.rtir)
            };

        case UPDATE_SITE_ALERT:
            return {
                ...state,
                alerts: state.alerts.map(alert =>
                    alert.id === action.payload.id ? action.payload : alert
                )
            };

        case EXPORT_MISP:
            return {
                ...state,
                sites: state.sites.map(site =>
                    site.id === action.payload.id 
                        ? { ...site, misp_event_id: action.payload.misp_event_id }
                        : site
                )
            };

        case GET_SITE_STATISTICS:
            return {
                ...state,
                statistics: action.payload
            };

        case GET_SITES_ALL:
            return { ...state, allSites: Array.isArray(action.payload) ? action.payload : [] };

        case GET_SITE_ALERTS_ALL:
            return { ...state, allAlerts: Array.isArray(action.payload) ? action.payload : [] };

        default:
            return state;
    }
}